import React, { useState, useEffect } from 'react';
import { adminService } from '../services/api';
import toast from 'react-hot-toast';
import { 
  Building2, 
  Users, 
  PawPrint, 
  Droplets,
  UserX,
  UserCheck,
  Search
} from 'lucide-react';

export default function AdminPage() {
  const [stats, setStats] = useState({ farms: 0, users: 0, animals: 0, milkRecords: 0 });
  const [farms, setFarms] = useState([]);
  const [users, setUsers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [activeTab, setActiveTab] = useState('users'); // users or farms
  const [searchQuery, setSearchQuery] = useState('');

  useEffect(() => {
    fetchAdminData();
  }, []);

  const fetchAdminData = async () => {
    setLoading(true);
    try {
      const [statsRes, farmsRes, usersRes] = await Promise.all([
        adminService.stats(),
        adminService.listFarms(),
        adminService.listUsers()
      ]);
      setStats(statsRes.data.stats);
      setFarms(farmsRes.data.farms);
      setUsers(usersRes.data.users);
    } catch (err) {
      console.error(err);
      toast.error('Admin verileri yüklenirken bir hata oluştu.');
    } finally {
      setLoading(false);
    }
  };

  const handleToggleUserStatus = async (userId, currentStatus) => {
    const nextStatus = currentStatus === 'active' ? 'suspended' : 'active';
    
    try {
      await adminService.toggleUserStatus(userId, nextStatus);
      toast.success(`Kullanıcı başarıyla ${nextStatus === 'active' ? 'aktifleştirildi' : 'askıya alındı'}.`);
      // Update local state
      setUsers(users.map(u => u.id === userId ? { ...u, status: nextStatus } : u));
      // Update user count if status affects it, or just reload stats
      const statsRes = await adminService.stats();
      setStats(statsRes.data.stats);
    } catch (err) {
      console.error(err);
      toast.error(err.response?.data?.error || 'Kullanıcı durumu güncellenemedi.');
    }
  };

  const filteredUsers = users.filter(u => 
    u.full_name?.toLowerCase().includes(searchQuery.toLowerCase()) ||
    u.email?.toLowerCase().includes(searchQuery.toLowerCase()) ||
    u.farm?.name?.toLowerCase().includes(searchQuery.toLowerCase())
  );

  const filteredFarms = farms.filter(f => 
    f.name?.toLowerCase().includes(searchQuery.toLowerCase()) ||
    f.location?.toLowerCase().includes(searchQuery.toLowerCase()) ||
    f.license_type?.toLowerCase().includes(searchQuery.toLowerCase())
  );

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-[400px]">
        <div className="w-12 h-12 border-4 border-teal-600 border-t-transparent rounded-full animate-spin" />
      </div>
    );
  }

  return (
    <div className="space-y-8 animate-fade-in">
      {/* Header */}
      <div>
        <h1 className="text-3xl font-black text-slate-900 tracking-tight">Sistem Yönetici Paneli</h1>
        <p className="text-sm text-slate-500 font-medium mt-1">Tüm çiftliklerin ve kullanıcıların genel yönetimi</p>
      </div>

      {/* Stats Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        {[
          { label: 'Çiftlikler', value: stats.farms, icon: Building2, color: 'from-teal-500 to-emerald-500', shadow: 'shadow-teal-500/10' },
          { label: 'Kullanıcılar', value: stats.users, icon: Users, color: 'from-blue-500 to-indigo-500', shadow: 'shadow-blue-500/10' },
          { label: 'Toplam Hayvan', value: stats.animals, icon: PawPrint, color: 'from-amber-500 to-orange-500', shadow: 'shadow-amber-500/10' },
          { label: 'Süt Kayıtları', value: stats.milkRecords, icon: Droplets, color: 'from-sky-500 to-blue-500', shadow: 'shadow-sky-500/10' },
        ].map((stat, i) => (
          <div key={i} className={`bg-white rounded-3xl p-6 border border-slate-100 shadow-xl ${stat.shadow} flex items-center justify-between`}>
            <div>
              <p className="text-xs font-bold text-slate-400 uppercase tracking-wider">{stat.label}</p>
              <h3 className="text-3xl font-black text-slate-950 mt-1">{stat.value}</h3>
            </div>
            <div className={`p-4 rounded-2xl bg-gradient-to-br ${stat.color} text-white`}>
              <stat.icon className="w-6 h-6" />
            </div>
          </div>
        ))}
      </div>

      {/* Main Content Card */}
      <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-xl overflow-hidden">
        {/* Tab Selector & Search */}
        <div className="p-6 border-b border-slate-100 flex flex-col md:flex-row md:items-center md:justify-between gap-4">
          <div className="flex gap-2 p-1.5 bg-slate-50 rounded-2xl w-fit">
            <button 
              onClick={() => { setActiveTab('users'); setSearchQuery(''); }}
              className={`px-6 py-2.5 rounded-xl text-sm font-bold tracking-tight transition-all ${activeTab === 'users' ? 'bg-white text-slate-900 shadow-md shadow-slate-900/5' : 'text-slate-500 hover:text-slate-900'}`}
            >
              Kullanıcı Yönetimi
            </button>
            <button 
              onClick={() => { setActiveTab('farms'); setSearchQuery(''); }}
              className={`px-6 py-2.5 rounded-xl text-sm font-bold tracking-tight transition-all ${activeTab === 'farms' ? 'bg-white text-slate-900 shadow-md shadow-slate-900/5' : 'text-slate-500 hover:text-slate-900'}`}
            >
              Çiftlik Kayıtları
            </button>
          </div>

          <div className="relative max-w-md w-full">
            <Search className="w-4 h-4 text-slate-400 absolute left-4 top-1/2 -translate-y-1/2" />
            <input 
              type="text" 
              placeholder={`${activeTab === 'users' ? 'Kullanıcı adı, email veya çiftlik' : 'Çiftlik adı veya lokasyon'} ara...`}
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="w-full pl-11 pr-4 py-3 bg-slate-50 border border-slate-200/50 rounded-2xl text-sm focus:outline-none focus:ring-2 focus:ring-teal-500/20 focus:border-teal-500 transition-all font-medium"
            />
          </div>
        </div>

        {/* Tab Panels */}
        <div className="overflow-x-auto">
          {activeTab === 'users' ? (
            <table className="w-full text-left border-collapse">
              <thead>
                <tr className="bg-slate-50/50 text-[10px] font-black text-slate-400 uppercase tracking-widest border-b border-slate-100">
                  <th className="py-4 px-6">Ad Soyad / E-posta</th>
                  <th className="py-4 px-6">Bağlı Çiftlik</th>
                  <th className="py-4 px-6">Rol</th>
                  <th className="py-4 px-6">Kayıt Tarihi</th>
                  <th className="py-4 px-6">Durum</th>
                  <th className="py-4 px-6 text-right">İşlemler</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100/50">
                {filteredUsers.length > 0 ? (
                  filteredUsers.map(user => (
                    <tr key={user.id} className="hover:bg-slate-50/30 transition-colors font-medium text-sm text-slate-600">
                      <td className="py-4 px-6">
                        <div>
                          <p className="font-bold text-slate-900">{user.full_name}</p>
                          <p className="text-xs text-slate-400 font-medium mt-0.5">{user.email}</p>
                        </div>
                      </td>
                      <td className="py-4 px-6">
                        <span className="font-bold text-slate-800">{user.farm?.name || 'Belirtilmemiş'}</span>
                      </td>
                      <td className="py-4 px-6">
                        <span className={`px-2.5 py-1 rounded-lg text-xs font-bold uppercase tracking-wider ${
                          user.role === 'owner' ? 'bg-teal-50 text-teal-700' :
                          user.role === 'admin' ? 'bg-indigo-50 text-indigo-700' :
                          user.role === 'veterinarian' ? 'bg-sky-50 text-sky-700' : 'bg-slate-100 text-slate-700'
                        }`}>
                          {user.role === 'owner' ? 'Çiftlik Sahibi' : 
                           user.role === 'admin' ? 'Yönetici' : 
                           user.role === 'veterinarian' ? 'Veteriner' : 'Personel'}
                        </span>
                      </td>
                      <td className="py-4 px-6 text-xs text-slate-400">
                        {new Date(user.created_at || user.createdAt).toLocaleDateString('tr-TR')}
                      </td>
                      <td className="py-4 px-6">
                        <span className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-bold ${
                          user.status === 'active' ? 'bg-green-50 text-green-700' : 'bg-red-50 text-red-700'
                        }`}>
                          <span className={`w-1.5 h-1.5 rounded-full ${user.status === 'active' ? 'bg-green-600' : 'bg-red-600'}`} />
                          {user.status === 'active' ? 'Aktif' : 'Askıda'}
                        </span>
                      </td>
                      <td className="py-4 px-6 text-right">
                        <button
                          onClick={() => handleToggleUserStatus(user.id, user.status)}
                          className={`inline-flex items-center gap-1.5 px-4 py-2 rounded-xl text-xs font-black transition-all hover:scale-105 active:scale-95 ${
                            user.status === 'active' 
                              ? 'bg-red-50 text-red-600 hover:bg-red-100' 
                              : 'bg-green-50 text-green-600 hover:bg-green-100'
                          }`}
                        >
                          {user.status === 'active' ? (
                            <>
                              <UserX className="w-3.5 h-3.5" />
                              Askıya Al
                            </>
                          ) : (
                            <>
                              <UserCheck className="w-3.5 h-3.5" />
                              Aktifleştir
                            </>
                          )}
                        </button>
                      </td>
                    </tr>
                  ))
                ) : (
                  <tr>
                    <td colSpan="6" className="py-8 text-center text-slate-400 font-medium">Kullanıcı bulunamadı.</td>
                  </tr>
                )}
              </tbody>
            </table>
          ) : (
            <table className="w-full text-left border-collapse">
              <thead>
                <tr className="bg-slate-50/50 text-[10px] font-black text-slate-400 uppercase tracking-widest border-b border-slate-100">
                  <th className="py-4 px-6">Çiftlik Adı / E-posta</th>
                  <th className="py-4 px-6">Lokasyon</th>
                  <th className="py-4 px-6">Lisans Türü</th>
                  <th className="py-4 px-6">Kayıt Tarihi</th>
                  <th className="py-4 px-6">Abonelik Durumu</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100/50">
                {filteredFarms.length > 0 ? (
                  filteredFarms.map(farm => (
                    <tr key={farm.id} className="hover:bg-slate-50/30 transition-colors font-medium text-sm text-slate-600">
                      <td className="py-4 px-6">
                        <div>
                          <p className="font-bold text-slate-900">{farm.name}</p>
                          <p className="text-xs text-slate-400 font-medium mt-0.5">{farm.email}</p>
                        </div>
                      </td>
                      <td className="py-4 px-6 font-bold text-slate-700">{farm.location || 'Belirtilmemiş'}</td>
                      <td className="py-4 px-6">
                        <span className="px-2.5 py-1 bg-amber-50 text-amber-700 rounded-lg text-xs font-bold uppercase tracking-wider">
                          {farm.license_type === 'professional' ? 'Profesyonel' : 'Standart'}
                        </span>
                      </td>
                      <td className="py-4 px-6 text-xs text-slate-400">
                        {new Date(farm.created_at || farm.createdAt).toLocaleDateString('tr-TR')}
                      </td>
                      <td className="py-4 px-6">
                        <span className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-bold ${
                          farm.subscription_status === 'active' ? 'bg-green-50 text-green-700' : 'bg-red-50 text-red-700'
                        }`}>
                          <span className={`w-1.5 h-1.5 rounded-full ${farm.subscription_status === 'active' ? 'bg-green-600' : 'bg-red-600'}`} />
                          {farm.subscription_status === 'active' ? 'Aktif' : 'Pasif'}
                        </span>
                      </td>
                    </tr>
                  ))
                ) : (
                  <tr>
                    <td colSpan="5" className="py-8 text-center text-slate-400 font-medium">Çiftlik bulunamadı.</td>
                  </tr>
                )}
              </tbody>
            </table>
          )}
        </div>
      </div>
    </div>
  );
}
